import java.io.*;
import java.util.*;

public class Main {
    static final InputStream is = System.in;
    static final byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;

    static int rb() throws IOException {
        if (ptr == len) {
            len = is.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = rb();
        while (c != '-' && (c < '0' || c > '9')) c = rb();
        boolean neg = c == '-';
        if (neg) c = rb();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = rb();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = rb();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = rb();
        StringBuilder sb = new StringBuilder();
        while (c != -1 && c != ' ' && c != '\n' && c != '\r' && c != '\t') {
            sb.append((char) c);
            c = rb();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        StringBuilder sb = new StringBuilder();
        int[] forward = new int[26], back = new int[26];
        for (int k = 0; k < n; k++) {
            String a = next(), b = next();
            // Both directions must be consistent: a letter permutation preserves which positions are equal.
            Arrays.fill(forward, -1);
            Arrays.fill(back, -1);
            boolean ok = true;
            for (int i = 0; i < a.length() && ok; i++) {
                int x = a.charAt(i) - 'a', y = b.charAt(i) - 'a';
                if ((forward[x] >= 0 && forward[x] != y) || (back[y] >= 0 && back[y] != x)) ok = false;
                forward[x] = y;
                back[y] = x;
            }
            sb.append(ok ? '1' : '0').append(k + 1 < n ? ' ' : '\n');
        }
        System.out.print(sb);
    }
}

package main

import (
	"bufio"
	"os"
)

var reader = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	c, _ := reader.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' || c == '\t' {
		c, _ = reader.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = reader.ReadByte()
	}
	n := 0
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = reader.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}

func readToken() string {
	c, err := reader.ReadByte()
	for err == nil && (c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		c, err = reader.ReadByte()
	}
	var tok []byte
	for err == nil && !(c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		tok = append(tok, c)
		c, err = reader.ReadByte()
	}
	return string(tok)
}

func main() {
	n := readInt()
	out := make([]byte, 0, 2*n)
	for k := 0; k < n; k++ {
		a, b := readToken(), readToken()
		// Both directions must be consistent: a letter permutation preserves which positions are equal.
		var forward, back [26]int
		for i := range forward {
			forward[i], back[i] = -1, -1
		}
		ok := true
		for i := 0; i < len(a) && ok; i++ {
			x, y := int(a[i]-'a'), int(b[i]-'a')
			if (forward[x] >= 0 && forward[x] != y) || (back[y] >= 0 && back[y] != x) {
				ok = false
			}
			forward[x], back[y] = y, x
		}
		if ok {
			out = append(out, '1')
		} else {
			out = append(out, '0')
		}
		if k+1 < n {
			out = append(out, ' ')
		} else {
			out = append(out, '\n')
		}
	}
	os.Stdout.Write(out)
}
